import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { filePathToRoute } from "../runtime/routes";
import type { FetchMode } from "../fetch-mode";
import type { ResolvedI18n } from "../i18n";
import { scanPages } from "./layouts";

/** Source of `.noofpi/doofpi.d.ts`: registers the `routes` export of `server/doofpi.ts` as the `localRoutes` (`lfetch`) of `useDoofpi()` and the `doofpi.fetch` mode of the config as its default */
export function doofpiTypes(fetch: FetchMode = "lfetch"): string {
  return [
    "// Generated by noofpi, do not edit",
    'import type * as server from "../server/doofpi";',
    "",
    'declare module "noofpi/runtime" {',
    "  interface Register {",
    "    localRoutes: typeof server extends { routes: infer R } ? R : any;",
    `    defaultFetch: "${fetch}";`,
    "  }",
    "}",
    "",
  ].join("\n");
}

const PARAM = /:(\w+)(\(\.\*\)\*)?/g;

/** `/users/:id` -> `{ id: string | number }` ; catch-all `/docs/:slug(.*)*` -> `{ slug: string[] }` */
function paramsType(route: string): string {
  const fields = [...route.matchAll(PARAM)].map(
    ([, name, catchAll]) =>
      `${name}: ${catchAll ? "string[]" : "string | number"}`,
  );
  return fields.length ? `{ ${fields.join("; ")} }` : "{}";
}

/** Source of `.noofpi/routes.d.ts`: registers the page routes (paths and their params) with `navigateTo()` */
export function routeTypes(routes: string[]): string {
  return [
    "// Generated by noofpi, do not edit",
    'declare module "noofpi/runtime" {',
    "  interface Register {",
    "    pages: {",
    ...[...routes]
      .sort()
      .map((route) => `      ${JSON.stringify(route)}: ${paramsType(route)};`),
    "    };",
    "  }",
    "}",
    "export {};",
    "",
  ].join("\n");
}

/** Writes `.noofpi/routes.d.ts` from the files in `app/pages`; unchanged content is left alone */
export function writeRouteTypes(root: string): void {
  const routes = Object.keys(scanPages(root, () => true)).map(filePathToRoute);
  const file = path.join(root, ".noofpi/routes.d.ts");
  const content = routeTypes(routes);
  if (existsSync(file) && readFileSync(file, "utf8") === content) return;
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, content);
}

/** `app/locales/<locale>.{ts,js,json}` as a path relative to the project root, `undefined` when there is none */
export function findLocaleFile(
  root: string,
  locale: string,
): string | undefined {
  return ["ts", "js", "json"]
    .map((extension) => `app/locales/${locale}.${extension}`)
    .find((file) => existsSync(path.join(root, file)));
}

/**
 * Source of `.noofpi/i18n.d.ts`: registers the locales and the messages of the default locale (its file, as a
 * path relative to `.noofpi/`) with `t()`. Without a file only the locales are registered.
 */
export function i18nTypes(
  i18n: ResolvedI18n,
  defaultLocaleFile?: string,
): string {
  const specifier = defaultLocaleFile?.replace(/\.(ts|js)$/, "");
  return [
    "// Generated by noofpi, do not edit",
    ...(specifier
      ? [`import type messages from ${JSON.stringify("../" + specifier)};`]
      : []),
    "",
    'declare module "noofpi/runtime" {',
    "  interface Register {",
    ...(specifier ? ["    messages: typeof messages;"] : []),
    `    locales: ${i18n.locales.map((locale) => JSON.stringify(locale)).join(" | ")};`,
    "  }",
    "}",
    "export {};",
    "",
  ].join("\n");
}

/** Writes `.noofpi/i18n.d.ts` when `i18n` is configured; unchanged content is left alone */
export function writeI18nTypes(
  root: string,
  i18n: ResolvedI18n | undefined,
): void {
  if (!i18n) return;
  const file = path.join(root, ".noofpi/i18n.d.ts");
  const content = i18nTypes(i18n, findLocaleFile(root, i18n.defaultLocale));
  if (existsSync(file) && readFileSync(file, "utf8") === content) return;
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, content);
}

/** Writes `.noofpi/doofpi.d.ts` when the project has a `server/doofpi.ts`; unchanged content is left alone */
export function writeDoofpiTypes(root: string, fetch?: FetchMode): void {
  if (!existsSync(path.join(root, "server/doofpi.ts"))) return;
  const file = path.join(root, ".noofpi/doofpi.d.ts");
  const content = doofpiTypes(fetch);
  if (existsSync(file) && readFileSync(file, "utf8") === content) return;
  mkdirSync(path.dirname(file), { recursive: true });
  writeFileSync(file, content);
}
